/**
 * Tells a demo visitor that the results are produced by AI models (EU AI Act
 * art. 50). The downloads carry the same information in a machine-readable
 * form; see api/utils/ai_marking.py.
 */
export const AI_NOTICE_TEXT =
  "Results on this page are generated by AI models and can be wrong. Check them before you use them.";

export function AiNotice() {
  return (
    <p data-testid="ai-notice" className="text-muted-foreground mb-6 text-xs">
      {AI_NOTICE_TEXT}
    </p>
  );
}
